{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C16"],
      "claim": "SHP099, a piperidine-aminopyrimidine analogue with a polar heteroaromatic core, showed brain-plasma ratios >1 in mice after oral dosing, demonstrating that this chemotype achieves meaningful CNS exposure despite moderate polarity.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "AN317, an N-heteroaryl piperidine-related CNS agent, exhibited high brain-to-plasma ratios in mice and rats, supporting brain penetration for similar piperidine-heteroaromatic scaffolds.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "A triazole-pyrimidine radiotracer with a heteroaromatic azole/azine core showed moderate brain uptake (3.60% ID/g at 2 min) in mice, indicating that nitrogen-rich heteroaromatic molecules can cross the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "Tirabrutinib, a piperidine-fused aminopyrimidine analogue, was classified as permeable with measurable brain exposure in rats (unbound brain-to-plasma ratio 8.5% at Cmax), showing that even moderate unbound partitioning can still provide meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "PET imaging of ABT-418 in rhesus monkeys showed rapid brain uptake, providing direct in vivo evidence that small heteroaromatic amines with polar features penetrate the BBB.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Pass. Multiple high-transfer in vivo CNS penetration studies on structurally related piperidine/heteroaromatic molecules demonstrate meaningful brain access despite moderate polarity; the physicochemical prior is overridden by direct experimental evidence.",
  "evidence_gaps": [
    "No direct brain/plasma or CSF measurement for the exact query molecule.",
    "P-glycoprotein/BCRP substrate status of the query is not experimentally defined.",
    "Human CNS pharmacokinetic data are absent."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

